import React, { useEffect, useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { VideoPlayer } from './components/VideoPlayer';
import { ChannelGrid } from './components/ChannelGrid';
import { FavoritesBar } from './components/FavoritesBar'; 
import { AiChatPet } from './components/AiChatPet';
import { ScheduleList } from './components/ScheduleList';
import { AlarmModal } from './components/AlarmModal';
import { SettingsModal } from './components/SettingsModal';
import { fetchCountries, fetchChannelsByCountry, fetchRadioStations, fetchGlobalChannelsByCategory, getTimezone, GLOBAL_COUNTRY } from './services/iptvService';
import { Country, Channel, AppTheme, Reminder, Language, AppSettings } from './types';
import { Menu, RefreshCw, Shuffle, History, AlarmClock, Sparkles, Terminal, Languages, Loader2 } from 'lucide-react';

const THEMES: AppTheme[] = [
  {
    id: 'cyber',
    name: { zh: '赛博霓虹 2.0', en: 'Cyber 2.0' },
    type: 'glass',
    styles: {
      bgMain: 'bg-aurora-cyber', bgSidebar: 'bg-black/60 backdrop-blur-[80px] border-r border-white/10',
      textMain: 'text-white font-sans tracking-tight', textDim: 'text-cyan-400/50', border: 'border-white/10',
      card: 'glass-card hover:border-cyan-500/40 transition-all duration-500',
      cardHover: 'hover:shadow-[0_0_50px_rgba(6,182,212,0.2)] hover:-translate-y-1', button: 'bg-white/5 hover:bg-white/10 text-white',
      buttonActive: 'bg-cyan-500 text-black font-black shadow-[0_0_30px_rgba(6,182,212,0.5)]', buttonPrimary: 'bg-cyan-400 text-black hover:bg-white',
      input: 'bg-black/40 border-white/10 text-white focus:border-cyan-500', font: 'font-sans', layoutShape: 'rounded-[2rem]', shadow: 'shadow-2xl', accentColor: 'text-cyan-400', bgPattern: 'bg-scanline'
    }
  },
  {
    id: 'candy',
    name: { zh: '梦幻马卡龙', en: 'Macaron' },
    type: 'kids',
    styles: {
      bgMain: 'bg-aurora-candy', bgSidebar: 'bg-white/70 backdrop-blur-2xl border-r-4 border-rose-100',
      textMain: 'text-rose-600 font-bold font-sans', textDim: 'text-rose-300', border: 'border-rose-100',
      card: 'bg-white/80 border-none shadow-[0_20px_40px_rgba(244,63,94,0.08)]',
      cardHover: 'hover:scale-105 hover:-rotate-1 active:scale-95', button: 'bg-rose-50 text-rose-500',
      buttonActive: 'bg-rose-500 text-white font-black shadow-lg', buttonPrimary: 'bg-rose-400 text-white hover:bg-rose-500',
      input: 'bg-white/60 border-2 border-rose-100 text-rose-600', font: 'font-sans', layoutShape: 'rounded-[3rem]', shadow: 'shadow-2xl', accentColor: 'text-rose-400'
    }
  },
  {
    id: 'synth',
    name: { zh: '幻紫呼吸', en: 'Synthwave' },
    type: 'glass',
    styles: {
      bgMain: 'bg-aurora-synth', bgSidebar: 'bg-[#0a001a]/70 backdrop-blur-[60px] border-r border-[#ff00ff]/20',
      textMain: 'text-[#00ffff] font-sans tracking-widest text-glow', textDim: 'text-[#ff00ff]/50', border: 'border-[#ff00ff]/20',
      card: 'bg-[#1a0033]/40 border border-[#ff00ff]/10 hover:border-[#ff00ff]/60',
      cardHover: 'hover:shadow-[0_0_60px_rgba(255,0,255,0.15)]', button: 'bg-[#330066]/50 text-[#00ffff]',
      buttonActive: 'bg-gradient-to-r from-[#ff00ff] to-[#00ffff] text-black font-black', buttonPrimary: 'bg-[#ff00ff] text-white',
      input: 'bg-[#0a001a]/40 border-[#ff00ff]/20 text-[#00ffff]', font: 'font-sans', layoutShape: 'rounded-2xl', shadow: 'shadow-2xl', accentColor: 'text-[#ff00ff]'
    }
  }
];

const FAVORITES_COUNTRY: Country = { name: '我的频道', code: 'FAVORITES', languages: [], flag: '💖' };
const GLOBAL_EXPLORE_COUNTRY: Country = { name: '星际搜索', code: 'GLOBAL_EXPLORE', languages: ['en'], flag: '🛰️' };
const HOT_TAGS = ['新闻', '体育', '电影', '音乐', '少儿', '探索', '时尚', '景观', '经典'];

const TRANSLATIONS = {
  zh: {
    loading: '正在校准卫星轨道...',
    nodesSynchronized: '个全球信道在线',
    nodeTime: '轨道同步时间',
    discoveryTerminal: 'AI 标签云搜索',
    activityLog: '播放历史',
    logsEmpty: '星历表暂无记录',
    randomStation: '量子随机换台',
    reset: '重置',
    favoritesTitle: '收藏夹',
    global: '全球'
  },
  en: {
    loading: 'Calibrating satellites...',
    nodesSynchronized: 'Channels Online',
    nodeTime: 'Orbital Time',
    discoveryTerminal: 'AI Tag Explore',
    activityLog: 'Recent Logs',
    logsEmpty: 'No logs found',
    randomStation: 'Quantum Shuffle',
    reset: 'RESET',
    favoritesTitle: 'Saved',
    global: 'Global'
  }
};

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>(() => (localStorage.getItem('app_lang') as Language) || 'zh');
  const [isAppReady, setIsAppReady] = useState(false);
  const [countries, setCountries] = useState<Country[]>([]);
  const [selectedCountry, setSelectedCountry] = useState<Country | null>(null);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [currentChannel, setCurrentChannel] = useState<Channel | null>(null);
  const [history, setHistory] = useState<Channel[]>([]);
  const [localTime, setLocalTime] = useState('--:--:--');
  const [loadingChannels, setLoadingChannels] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [mode, setMode] = useState<'tv' | 'radio'>('tv');
  const [favorites, setFavorites] = useState<Channel[]>([]);
  const [currentTheme, setCurrentTheme] = useState<AppTheme>(THEMES[0]);
  const [channelFilter, setChannelFilter] = useState('');
  const [discoveryTag, setDiscoveryTag] = useState<string | null>(null);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [showSchedule, setShowSchedule] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [activeAlarm, setActiveAlarm] = useState<Reminder | null>(null);
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('app_settings');
    return saved ? JSON.parse(saved) : { enableSound: true };
  });

  const t = TRANSLATIONS[lang];

  useEffect(() => {
    localStorage.setItem('app_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('app_lang', lang);
  }, [lang]);

  useEffect(() => {
    const init = async () => {
      try {
        const data = await fetchCountries();
        const globalNode = data.find(c => c.code === 'GLOBAL') || GLOBAL_COUNTRY;
        setCountries([FAVORITES_COUNTRY, ...data]);

        const savedThemeId = localStorage.getItem('app_theme_id');
        if (savedThemeId) {
            const th = THEMES.find(th => th.id === savedThemeId);
            if (th) setCurrentTheme(th);
        }

        setSelectedCountry(globalNode);

        const savedFavs = localStorage.getItem('global_favorites');
        if (savedFavs) setFavorites(JSON.parse(savedFavs));
        const savedReminders = localStorage.getItem('global_reminders');
        if (savedReminders) setReminders(JSON.parse(savedReminders));
        const savedHistory = localStorage.getItem('app_history');
        if (savedHistory) setHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error("Initialization failed", e);
      } finally {
        setTimeout(() => setIsAppReady(true), 1500);
      }
    };
    init();
  }, []);

  useEffect(() => {
    const timer = setInterval(() => {
      try {
        const tz = (selectedCountry && selectedCountry.code !== 'GLOBAL') ? getTimezone(selectedCountry.code) : 'UTC';
        setLocalTime(new Intl.DateTimeFormat('zh-CN', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: tz }).format(new Date()));
        const nowStr = new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false });
        const trigger = reminders.find(r => r.timeStr === nowStr);
        if (trigger && !activeAlarm) setActiveAlarm(trigger);
      } catch (e) { setLocalTime('--:--:--'); }
    }, 1000);
    return () => clearInterval(timer);
  }, [selectedCountry, reminders, activeAlarm]);

  const loadContent = async (refresh = false) => {
    if (!selectedCountry) return;
    setLoadingChannels(true);
    try {
      let data: Channel[] = [];
      if (discoveryTag) {
        data = await fetchGlobalChannelsByCategory(discoveryTag);
      } else {
        data = mode === 'tv' ? await fetchChannelsByCountry(selectedCountry.code, refresh) : await fetchRadioStations(selectedCountry.code, refresh);
      }
      setChannels(data);
      if (data.length > 0 && (!currentChannel || refresh)) {
          setCurrentChannel(data.find(c => c.url) || data[0]);
      }
    } catch (err) { setChannels([]); }
    finally { setLoadingChannels(false); }
  };

  useEffect(() => { if (isAppReady) loadContent(); }, [selectedCountry, mode, isAppReady, discoveryTag]);

  const handleChannelSelect = (channel: Channel) => {
    setCurrentChannel(channel);
    const newHistory = [channel, ...history.filter(c => c.id !== channel.id)].slice(0, 15);
    setHistory(newHistory);
    localStorage.setItem('app_history', JSON.stringify(newHistory));
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleThemeChange = (theme: AppTheme) => {
    document.body.classList.add('glitch-transition');
    setCurrentTheme(theme);
    localStorage.setItem('app_theme_id', theme.id);
    setTimeout(() => document.body.classList.remove('glitch-transition'), 300);
  };

  const toggleFavorite = (channel: Channel) => {
    setFavorites(prev => {
      const isFav = prev.some(f => f.id === channel.id);
      const next = isFav ? prev.filter(f => f.id !== channel.id) : [...prev, channel];
      localStorage.setItem('global_favorites', JSON.stringify(next));
      return next;
    });
  };

  if (!isAppReady) return (
    <div className="h-screen w-full bg-[#050508] flex flex-col items-center justify-center text-cyan-500">
      <div className="relative mb-8">
        <div className="w-24 h-24 border-t-4 border-cyan-500 rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
            <Loader2 className="w-10 h-10 animate-pulse" />
        </div>
      </div>
      <div className="font-mono text-[11px] uppercase tracking-[0.6em] animate-pulse">{t.loading}</div>
    </div>
  );

  const { styles } = currentTheme;

  return (
    <div className={`flex h-screen w-full ${styles.bgMain} ${styles.font} overflow-hidden relative`}>
      {styles.bgPattern && <div className={`fixed inset-0 ${styles.bgPattern} pointer-events-none z-[1] opacity-10`}></div>}

      <Sidebar 
        countries={countries} selectedCountry={discoveryTag ? GLOBAL_EXPLORE_COUNTRY : selectedCountry} 
        onSelectCountry={(c) => { setDiscoveryTag(null); setSelectedCountry(c); }}
        isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} mode={mode} onModeChange={setMode}
        themes={THEMES} currentTheme={currentTheme} onThemeChange={handleThemeChange}
        favorites={favorites} onSelectFavorite={handleChannelSelect} history={history}
        onImportM3U={() => {}} settings={settings} onToggleSound={() => setSettings(s => ({...s, enableSound: !s.enableSound}))} 
        onOpenSettings={() => setShowSettings(true)}
        reminders={reminders} onDeleteReminder={(id) => {
            const next = reminders.filter(r => r.id !== id);
            setReminders(next); localStorage.setItem('global_reminders', JSON.stringify(next));
        }} onPlayReminder={handleChannelSelect}
        lang={lang}
      />

      <main className="flex-1 flex flex-col h-full min-w-0 z-10 relative">
        <header className={`shrink-0 px-10 py-8 flex items-center justify-between border-b ${styles.border} ${styles.bgSidebar} backdrop-blur-3xl z-30 shadow-2xl`}>
            <div className="flex items-center gap-6">
                <button onClick={() => setSidebarOpen(true)} className={`md:hidden p-4 rounded-xl ${styles.card} ${styles.textMain}`}><Menu /></button>
                <div className="flex items-center gap-6">
                    <span className="text-5xl filter drop-shadow-[0_0_15px_rgba(255,255,255,0.3)] animate-float">{discoveryTag ? '☄️' : selectedCountry?.flag}</span>
                    <div className="flex flex-col">
                        <h1 className={`text-4xl font-black uppercase italic tracking-tighter leading-none ${styles.textMain} ${currentTheme.id === 'cyber' || currentTheme.id === 'synth' ? 'text-glow' : ''}`}>
                            {discoveryTag ? `${discoveryTag}` : selectedCountry?.name}
                        </h1>
                        <div className="flex items-center gap-2 mt-2">
                             <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse shadow-[0_0_10px_#22c55e]"></div>
                             <span className={`text-[10px] font-black tracking-widest uppercase opacity-60 ${styles.textDim}`}>
                                {channels.length} {t.nodesSynchronized}
                             </span>
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-10">
                <button 
                  onClick={() => setLang(lang === 'zh' ? 'en' : 'zh')}
                  className={`flex items-center gap-2 px-6 py-3 rounded-full border ${styles.border} ${styles.button} transition-all hover:scale-105 active:scale-95 shadow-lg group`}
                >
                  <Languages className="w-4 h-4 group-hover:rotate-12 transition-transform" />
                  <span className="text-[10px] font-black uppercase tracking-widest">{lang === 'zh' ? 'EN' : '中文'}</span>
                </button>

                <div className="hidden lg:flex flex-col items-end">
                    <span className={`text-[9px] font-black uppercase tracking-widest ${styles.textDim}`}>{t.nodeTime}</span>
                    <span className={`text-xl font-mono font-black ${styles.textMain}`}>{localTime}</span>
                </div>
                <div className="flex items-center gap-4">
                    <button onClick={() => setShowSchedule(true)} className={`p-4 rounded-2xl ${styles.button} hover:scale-110 active:scale-95 transition-all relative shadow-xl`}>
                        <AlarmClock className="w-5 h-5" />
                        {reminders.length > 0 && <span className="absolute top-3 right-3 w-3 h-3 bg-rose-500 rounded-full border-2 border-black animate-ping"></span>}
                    </button>
                    <button onClick={() => loadContent(true)} className={`p-4 rounded-2xl ${styles.button} hover:rotate-180 transition-all duration-1000 shadow-xl ${loadingChannels ? 'animate-spin' : ''}`}>
                        <RefreshCw className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className="px-10 py-10 max-w-[1700px] mx-auto">
                <div className="flex flex-col xl:flex-row gap-16">
                    <div className="flex-1 min-w-0 space-y-16">
                        <section className="space-y-10">
                            <VideoPlayer 
                              channel={currentChannel} country={discoveryTag ? GLOBAL_EXPLORE_COUNTRY : selectedCountry} theme={currentTheme}
                              isFavorite={!!currentChannel && favorites.some(f => f.id === currentChannel.id)}
                              onToggleFavorite={() => currentChannel && toggleFavorite(currentChannel)} 
                              onAutoSkip={() => {
                                  if (channels.length > 1) {
                                      const next = channels[Math.floor(Math.random()*channels.length)];
                                      handleChannelSelect(next);
                                  }
                              }}
                              lang={lang}
                            />
                            <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />
                        </section>

                        <section className="space-y-12">
                            <div className="flex flex-col space-y-10">
                                <h2 className={`text-4xl font-black uppercase italic tracking-tighter ${styles.textMain} flex items-center gap-5`}>
                                    <Sparkles className={`w-8 h-8 ${styles.accentColor} animate-pulse`} /> {t.discoveryTerminal}
                                </h2>
                                <div className="flex flex-wrap gap-4">
                                    {HOT_TAGS.map(tag => (
                                        <button 
                                            key={tag} onClick={() => { setDiscoveryTag(tag); setChannelFilter(''); }} 
                                            className={`px-8 py-4 ${styles.layoutShape} text-xs font-black border transition-all duration-500 transform active:scale-90 relative overflow-hidden group ${discoveryTag === tag ? styles.buttonActive : `${styles.button} opacity-50 hover:opacity-100`}`}
                                        >
                                            <span className="relative z-10"># {tag}</span>
                                            {discoveryTag === tag && <div className="absolute inset-0 bg-white/10 animate-pulse"></div>}
                                        </button>
                                    ))}
                                    {(discoveryTag || channelFilter) && (
                                        <button onClick={() => { setDiscoveryTag(null); setChannelFilter(''); }} className="px-8 py-4 rounded-full text-xs font-black bg-rose-500 text-white shadow-xl hover:bg-rose-600 transition-colors uppercase tracking-widest">{t.reset}</button>
                                    )}
                                </div>
                            </div>
                            <ChannelGrid 
                                channels={channels} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} 
                                loading={loadingChannels} mode={mode} theme={currentTheme} favorites={favorites} 
                                onToggleFavorite={toggleFavorite} externalFilter={channelFilter} onExternalFilterChange={setChannelFilter}
                            />
                        </section>
                    </div>

                    <div className="xl:w-[420px] shrink-0 space-y-12">
                        <div className="xl:sticky xl:top-12 space-y-12">
                            {/* 播放历史卡片 - 增加玻璃质感 */}
                            <div className={`${styles.card} p-10 ${styles.layoutShape} border ${styles.border} group overflow-hidden relative shadow-2xl transition-all`}>
                                <div className={`absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-cyan-500/50 to-transparent animate-shimmer`}></div>
                                <h3 className="text-[12px] font-black uppercase tracking-[0.5em] mb-10 opacity-50 flex items-center gap-4">
                                    <History className={`w-6 h-6 ${styles.accentColor}`} /> {t.activityLog}
                                </h3>
                                <div className="space-y-6 max-h-[400px] overflow-y-auto scrollbar-thin">
                                    {history.length > 0 ? history.map(h => (
                                        <div key={h.id} onClick={() => handleChannelSelect(h)} className={`flex items-center gap-6 p-5 rounded-[2rem] hover:bg-white/5 cursor-pointer group/item transition-all active:scale-95 border border-transparent hover:border-white/10`}>
                                            <div className="w-14 h-14 rounded-2xl bg-black/40 flex items-center justify-center shrink-0 overflow-hidden shadow-inner group-hover/item:rotate-12 transition-transform">
                                                {h.logo ? <img src={h.logo} className="w-full h-full object-contain p-2" /> : <History className="w-6 h-6 opacity-20" />}
                                            </div>
                                            <div className="flex flex-col min-w-0">
                                                <span className={`text-sm font-black uppercase truncate italic tracking-tighter ${styles.textMain}`}>{h.name}</span>
                                                <span className={`text-[10px] font-bold opacity-30 uppercase tracking-widest`}>{h.group || '频道'}</span>
                                            </div>
                                        </div>
                                    )) : (
                                        <div className="py-16 text-center text-[11px] font-black opacity-10 uppercase italic tracking-widest">{t.logsEmpty}</div>
                                    )}
                                </div>
                            </div>

                            {/* 随机换台按钮 - 增加呼吸感发光 */}
                            <button 
                                onClick={() => { if(channels.length > 0) handleChannelSelect(channels[Math.floor(Math.random()*channels.length)]) }} 
                                className={`w-full py-8 ${styles.buttonPrimary} ${styles.layoutShape} font-black uppercase text-[13px] flex items-center justify-center gap-5 shadow-2xl hover:translate-y-[-6px] active:translate-y-[2px] transition-all transform animate-breathe`}
                            >
                                <Shuffle className="w-6 h-6" /> {t.randomStation}
                            </button>

                            {/* 智能陪聊卡片 */}
                            <AiChatPet theme={currentTheme} currentChannels={channels} onSelectChannel={handleChannelSelect} lang={lang} />
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </main>

      <ScheduleList 
        reminders={reminders} isOpen={showSchedule} onClose={() => setShowSchedule(false)} 
        onDelete={(id) => { const next = reminders.filter(r => r.id !== id); setReminders(next); localStorage.setItem('global_reminders', JSON.stringify(next)); }}
        theme={currentTheme} onPlayChannel={(id) => { const ch = channels.find(c => c.id === id); if(ch) handleChannelSelect(ch); }}
        allChannels={channels}
      />
      <AlarmModal reminder={activeAlarm} onClose={() => setActiveAlarm(null)} onWatch={(id) => { const ch = channels.find(c => c.id === id); if(ch) handleChannelSelect(ch); setActiveAlarm(null); }} theme={currentTheme} />

      <SettingsModal 
        isOpen={showSettings} onClose={() => setShowSettings(false)}
        settings={settings} onToggleSound={() => setSettings(s => ({...s, enableSound: !s.enableSound}))}
        lang={lang} onToggleLang={() => setLang(l => l === 'zh' ? 'en' : 'zh')}
        theme={currentTheme}
        onClearHistory={() => { setHistory([]); localStorage.removeItem('app_history'); }}
        onClearFavorites={() => { setFavorites([]); localStorage.removeItem('global_favorites'); }}
      />
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import { Play, RefreshCw, Square, Star, Volume2, VolumeX, Maximize, Clock, Zap, Circle, AlertTriangle, Shuffle, WifiOff, Globe, ShieldAlert, Camera, Terminal } from 'lucide-react';
import { AppTheme, Channel, Country, Language } from '../types';

interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onAutoSkip?: () => void;
  lang: Language;
}

const TRANSLATIONS = {
  zh: {
    uplinkFailed: '信道握手失败',
    uplinkFailedDesc: '无法锁定卫星波束，请尝试切换物理节点。',
    signalTimeout: '接收超时',
    signalTimeoutDesc: '远程载波响应缓慢，可能存在区域性干扰。',
    frequencyLost: '载波丢失',
    frequencyLostDesc: '当前坐标信号中断，正在重新搜寻频道列表。',
    forceRelink: '强制对流',
    jumpNode: '跳跃至随机节点',
    recording: '正在写入存储',
    syncing: '同步中...',
    live: '实时传输',
    searching: '扫描中...',
    global: '公海信道',
    public: '公共'
  },
  en: {
    uplinkFailed: 'Handshake Failed',
    uplinkFailedDesc: 'Unable to lock beam. Switch physical node.',
    signalTimeout: 'Reception Timeout',
    signalTimeoutDesc: 'Carrier response slow. Check interference.',
    frequencyLost: 'Carrier Lost',
    frequencyLostDesc: 'Coordinate signal lost. Rescanning catalog.',
    forceRelink: 'Sync Now',
    jumpNode: 'Quantum Jump',
    recording: 'Writing Buffer',
    syncing: 'Syncing...',
    live: 'Real-time',
    searching: 'Scanning...',
    global: 'Global Link',
    public: 'Public'
  }
};

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, country, theme, isFavorite, onToggleFavorite, onAutoSkip, lang
}) => {
  const [activePlayerIndex, setActivePlayerIndex] = useState(0);
  const videoRefs = [useRef<HTMLVideoElement>(null), useRef<HTMLVideoElement>(null)];
  const hlsRefs = useRef<(Hls | null)[]>([null, null]);

  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [volume, setVolume] = useState(1);
  const [errorState, setErrorState] = useState<'none' | 'timeout' | 'fatal' | 'network'>('none');
  const retryCountRef = useRef(0);
  const MAX_RETRIES = 5; 

  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const recordingTimerRef = useRef<number | null>(null);
  const loadTimeoutRef = useRef<number | null>(null);

  const t = TRANSLATIONS[lang];

  const killAllPlayers = useCallback(() => {
    videoRefs.forEach(ref => {
      if (ref.current) {
        ref.current.pause();
        ref.current.removeAttribute('src');
        ref.current.load();
      }
    });
    hlsRefs.current.forEach((hls, idx) => {
      if (hls) {
        hls.destroy();
        hlsRefs.current[idx] = null;
      }
    });
  }, []);

  const resetState = () => {
    setErrorState('none');
    setLoading(true);
    retryCountRef.current = 0;
    if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
  };

  useEffect(() => {
    videoRefs.forEach(ref => {
      if (ref.current) ref.current.volume = volume;
    });
  }, [volume]);

  useEffect(() => {
    const url = channel?.url;
    if (!url) return;
    if (isRecording) stopRecording();
    killAllPlayers();
    resetState();

    const nextIndex = (activePlayerIndex + 1) % 2;
    const nextVideo = videoRefs[nextIndex].current;
    if (!nextVideo) return;

    loadTimeoutRef.current = window.setTimeout(() => {
        if (loading || !isPlaying) {
            setErrorState('timeout');
            setLoading(false);
        }
    }, 25000);

    if (url.includes('.m3u8') && Hls.isSupported()) {
      const hls = new Hls({
        maxBufferLength: 30,
        enableWorker: true,
        xhrSetup: (xhr) => { xhr.withCredentials = false; }
      });
      hlsRefs.current[nextIndex] = hls;
      hls.loadSource(url);
      hls.attachMedia(nextVideo);
      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        videoRefs.forEach((ref, idx) => { if (idx !== nextIndex && ref.current) ref.current.pause(); });
        nextVideo.play().catch(() => { setIsPlaying(false); });
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
        retryCountRef.current = 0;
      });
      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
            if (retryCountRef.current < MAX_RETRIES) {
                retryCountRef.current++;
                setTimeout(() => {
                  if (!hlsRefs.current[nextIndex]) return;
                  if (data.type === Hls.ErrorTypes.NETWORK_ERROR) hls.startLoad();
                  else hls.recoverMediaError();
                }, Math.pow(2, retryCountRef.current) * 500);
            } else {
                setErrorState(data.type === Hls.ErrorTypes.NETWORK_ERROR ? 'network' : 'fatal');
                setLoading(false);
                if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
            }
        }
      });
    } else {
      nextVideo.src = url;
      nextVideo.oncanplay = () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        nextVideo.play().catch(() => { setIsPlaying(false); });
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
      };
      nextVideo.onerror = () => { setErrorState('network'); setLoading(false); };
    }
    return () => { if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current); };
  }, [channel?.url]);

  useEffect(() => { return () => killAllPlayers(); }, [killAllPlayers]);

  const takeScreenshot = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video || errorState !== 'none' || loading) return;
    const canvas = document.createElement('canvas');
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const link = document.createElement('a');
    link.href = canvas.toDataURL('image/png');
    link.download = `Satellite_Capture_${channel?.name}_${Date.now()}.png`;
    link.click();
  };

  const startRecording = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video) return;
    const stream = (video as any).captureStream ? (video as any).captureStream() : null;
    if (!stream) return;
    const recorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
    mediaRecorderRef.current = recorder;
    chunksRef.current = [];
    recorder.ondataavailable = (e) => chunksRef.current.push(e.data);
    recorder.onstop = () => {
        const url = URL.createObjectURL(new Blob(chunksRef.current, { type: 'video/webm' }));
        const a = document.createElement('a'); a.href = url; a.download = `Rec_${channel?.name}.webm`; a.click();
    };
    recorder.start();
    setIsRecording(true);
    setRecordingDuration(0);
    recordingTimerRef.current = window.setInterval(() => setRecordingDuration(p => p + 1), 1000);
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    setIsRecording(false);
    if (recordingTimerRef.current) clearInterval(recordingTimerRef.current);
  };

  const { styles } = theme;
  const getErrorDisplay = () => {
      if (errorState === 'network') return { icon: <WifiOff className="w-16 h-16 text-amber-500 animate-pulse" />, title: t.uplinkFailed, desc: t.uplinkFailedDesc };
      if (errorState === 'timeout') return { icon: <Clock className="w-16 h-16 text-cyan-400 animate-spin" />, title: t.signalTimeout, desc: t.signalTimeoutDesc };
      return { icon: <AlertTriangle className="w-16 h-16 text-rose-500 animate-bounce" />, title: t.frequencyLost, desc: t.frequencyLostDesc };
  };

  const display = getErrorDisplay();

  return (
    <div className="relative w-full group animate-in zoom-in duration-1000">
      <div className={`relative w-full aspect-video bg-black ${styles.layoutShape} overflow-hidden border ${styles.border} shadow-[0_60px_150px_rgba(0,0,0,0.95)] transition-all duration-700 hover:border-white/20 animate-breathe`}>

        <div className="absolute inset-0 bg-gradient-to-tr from-cyan-500/5 via-transparent to-purple-500/5 opacity-50 z-0"></div>

        {errorState !== 'none' && (
            <div className="absolute inset-0 z-40 flex flex-col items-center justify-center text-center p-12 bg-black/90 backdrop-blur-[60px]">
                <div className="relative z-10 flex flex-col items-center space-y-10 animate-in fade-in zoom-in slide-in-from-bottom-12 duration-1000">
                    <div className="w-32 h-32 rounded-full bg-white/5 flex items-center justify-center border border-white/10 shadow-[0_0_100px_rgba(255,255,255,0.08)] relative group">
                        {display.icon}
                        <div className="absolute -inset-10 rounded-full border border-white/5 animate-ping opacity-10"></div>
                    </div>
                    <div>
                        <h3 className="text-white font-black text-5xl uppercase italic tracking-tighter mb-6 leading-tight">{display.title}</h3>
                        <p className="text-white/40 text-[12px] max-w-sm mx-auto leading-relaxed font-bold uppercase tracking-[0.2em]">{display.desc}</p>
                    </div>
                    <div className="flex flex-col sm:flex-row gap-6 pt-6">
                        <button onClick={() => window.location.reload()} className="px-14 py-5 bg-white text-black text-[12px] font-black uppercase rounded-full hover:bg-cyan-400 transition-all active:scale-95 flex items-center gap-4 shadow-2xl">
                            <RefreshCw className="w-5 h-5" /> {t.forceRelink}
                        </button>
                        <button onClick={onAutoSkip} className="px-14 py-5 bg-white/10 text-white text-[12px] font-black uppercase rounded-full border border-white/10 hover:bg-white/20 transition-all active:scale-95 flex items-center gap-4">
                            <Shuffle className="w-5 h-5" /> {t.jumpNode}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {[0, 1].map((index) => (
            <video
                key={index} ref={videoRefs[index]} playsInline muted={isMuted}
                className={`absolute inset-0 w-full h-full object-contain transition-opacity duration-1000 z-10 ${activePlayerIndex === index && errorState === 'none' ? 'opacity-100' : 'opacity-0'}`}
            />
        ))}

        <div className="absolute inset-0 pointer-events-none opacity-[0.05] bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_4px,3px_100%] z-20"></div>

        {isRecording && (
          <div className="absolute top-10 left-10 z-40 flex items-center gap-5 bg-black/70 backdrop-blur-3xl px-6 py-3 rounded-full border border-red-500/50 shadow-2xl animate-in slide-in-from-left duration-500">
             <div className="w-4 h-4 bg-red-600 rounded-full animate-pulse shadow-[0_0_20px_#dc2626] ripple-dot relative"></div>
             <span className="text-white text-[12px] font-black tracking-widest uppercase italic">{t.recording}</span>
             <span className="text-red-400 font-mono text-sm font-black border-l border-white/20 pl-5">
                 {Math.floor(recordingDuration/60).toString().padStart(2,'0')}:{(recordingDuration%60).toString().padStart(2,'0')}
             </span>
          </div>
        )}

        {loading && errorState === 'none' && (
             <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/85 backdrop-blur-3xl z-30 space-y-8 animate-in fade-in duration-500">
                <div className="relative w-24 h-24">
                    <div className="absolute inset-0 border-[8px] border-cyan-500/10 rounded-full"></div>
                    <div className="absolute inset-0 border-[8px] border-t-cyan-400 rounded-full animate-spin"></div>
                    <Terminal className="absolute inset-0 m-auto w-8 h-8 text-cyan-400 animate-pulse" />
                </div>
                <div className="text-[12px] text-cyan-400 font-mono font-black uppercase tracking-[0.6em] animate-pulse">{t.syncing}</div>
             </div>
        )}

        {/* Console UI - 更加现代化的悬浮玻璃面板 */}
        <div className={`absolute inset-x-10 bottom-10 p-8 bg-black/40 backdrop-blur-[60px] rounded-[2.5rem] border border-white/10 transition-all duration-700 shadow-3xl z-40 ${errorState !== 'none' ? 'opacity-0 translate-y-12' : 'opacity-0 translate-y-6 group-hover:opacity-100 group-hover:translate-y-0'}`}>
            <div className="flex flex-col md:flex-row items-center justify-between gap-8">
                <div className="flex items-center gap-8 min-w-0">
                    <button onClick={() => {
                        const v = videoRefs[activePlayerIndex].current;
                        if (isPlaying) v?.pause(); else v?.play();
                        setIsPlaying(!isPlaying);
                    }} className="w-20 h-20 bg-white text-black rounded-full flex items-center justify-center transition-all hover:scale-110 hover:bg-cyan-400 active:scale-90 shadow-[0_20px_50px_rgba(255,255,255,0.25)] group/btn">
                        {isPlaying ? <Square className="w-8 h-8 fill-current group-hover/btn:scale-110 transition-transform" /> : <Play className="w-8 h-8 fill-current ml-2 group-hover/btn:scale-110 transition-transform" />}
                    </button>
                    <div className="min-w-0">
                        <div className="flex items-center gap-4 mb-2">
                            <span className="px-3 py-1 bg-gradient-to-r from-red-600 to-rose-500 text-[10px] font-black text-white rounded-md shadow-xl uppercase tracking-widest animate-pulse">{t.live}</span>
                            <h4 className="text-white font-black text-2xl tracking-tighter truncate max-w-xl uppercase italic leading-none">
                                {channel?.name || t.searching}
                            </h4>
                        </div>
                        <div className="flex items-center gap-4 text-white/30 text-[11px] font-black uppercase tracking-[0.2em] mt-3">
                            <div className="flex items-center gap-2"><Zap className="w-4 h-4 text-cyan-400" /> {channel?.group || t.public}</div>
                            <div className="w-1.5 h-1.5 rounded-full bg-white/20"></div>
                            <div className="flex items-center gap-2"><Globe className="w-4 h-4" /> {country?.name || t.global}</div>
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    <button 
                        onClick={onToggleFavorite} 
                        className={`p-5 rounded-[22px] transition-all active:scale-90 shadow-2xl ${isFavorite ? 'bg-amber-400 text-black shadow-amber-500/40 scale-110' : 'bg-white/5 text-white hover:bg-white/10 border border-white/10'}`}
                        title="收藏"
                    >
                        <Star className={`w-6 h-6 ${isFavorite ? 'fill-current' : ''}`} />
                    </button>

                    <button onClick={takeScreenshot} title="卫星截屏" className="p-5 bg-white/5 text-white hover:bg-white/10 border border-white/10 rounded-[22px] transition-all active:scale-90 shadow-2xl">
                        <Camera className="w-6 h-6" />
                    </button>

                    <button onClick={isRecording ? stopRecording : startRecording} title="实时录制" className={`p-5 rounded-[22px] transition-all shadow-2xl ${isRecording ? 'bg-red-600 text-white animate-pulse' : 'bg-white/5 text-white hover:bg-white/10 border border-white/10'}`}>
                        <Circle className={`w-6 h-6 ${isRecording ? 'fill-current' : ''}`} />
                    </button>

                    <div className="h-12 w-[1px] bg-white/10 mx-3"></div>

                    <div className="flex items-center group/vol">
                      <button onClick={() => setIsMuted(!isMuted)} className="p-5 bg-white/5 border border-white/10 hover:bg-white/10 rounded-[22px] text-white transition-all shadow-2xl">
                          {isMuted || volume === 0 ? <VolumeX className="w-6 h-6 text-rose-500" /> : <Volume2 className="w-6 h-6" />}
                      </button>
                      <div className="w-0 overflow-hidden group-hover/vol:w-40 group-hover/vol:ml-6 transition-all duration-700 ease-out flex items-center">
                          <input type="range" min="0" max="1" step="0.01" value={isMuted ? 0 : volume} onChange={(e) => { const v = parseFloat(e.target.value); setVolume(v); if (v > 0) setIsMuted(false); }} className="w-36 h-2 accent-cyan-400 bg-white/10 rounded-full appearance-none cursor-pointer" />
                      </div>
                    </div>

                    <button onClick={() => videoRefs[activePlayerIndex].current?.requestFullscreen()} title="全屏视界" className="p-5 bg-white/5 border border-white/10 hover:bg-white/10 rounded-[22px] text-white transition-all shadow-2xl">
                        <Maximize className="w-6 h-6" />
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Channel, AppTheme } from '../types';
import { Tv, Search, Radio, Star, Play, Activity, Globe2, X, Command } from 'lucide-react';

interface ChannelGridProps {
  channels: Channel[];
  currentChannel: Channel | null;
  onSelectChannel: (channel: Channel) => void;
  loading: boolean;
  mode: 'tv' | 'radio';
  theme: AppTheme;
  favorites: Channel[];
  onToggleFavorite: (channel: Channel) => void;
  externalFilter?: string;
  onExternalFilterChange?: (filter: string) => void;
}

export const ChannelGrid: React.FC<ChannelGridProps> = ({ 
    channels, currentChannel, onSelectChannel, loading, mode, theme, favorites, onToggleFavorite,
    externalFilter = '', onExternalFilterChange
}) => {
  const [internalFilter, setInternalFilter] = useState('');
  const { styles } = theme;

  useEffect(() => { if (externalFilter) setInternalFilter(''); }, [externalFilter]);

  const filteredChannels = useMemo(() => {
    const activeFilter = (externalFilter || internalFilter).toLowerCase();
    if (!activeFilter) return channels;
    return channels.filter(c => c.name.toLowerCase().includes(activeFilter) || (c.group && c.group.toLowerCase().includes(activeFilter)));
  }, [channels, externalFilter, internalFilter]);

  if (loading) {
    return (
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6">
        {Array.from({ length: 18 }).map((_, i) => (
            <div key={i} className={`h-40 bg-white/5 ${styles.layoutShape} animate-pulse relative overflow-hidden`}>
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/[0.03] to-transparent animate-shimmer"></div>
            </div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-12">
      <div className={`flex items-center gap-6 p-6 ${styles.input} ${styles.layoutShape} border ${styles.border} shadow-3xl group transition-all duration-500 hover:border-white/20`}>
        <Search className={`w-6 h-6 ${styles.textDim} group-focus-within:text-cyan-400 transition-colors`} />
        <input 
            type="text"
            placeholder={externalFilter ? `节点过滤: ${externalFilter}` : "输入波段、频道名称或分类关键词..."}
            className="bg-transparent border-none focus:outline-none text-[14px] font-bold w-full placeholder:opacity-30 uppercase tracking-widest"
            value={internalFilter}
            onChange={(e) => {
                setInternalFilter(e.target.value);
                if (onExternalFilterChange) onExternalFilterChange('');
            }}
        />
        <div className="hidden md:flex items-center gap-2 opacity-20 group-focus-within:opacity-0 transition-opacity">
            <Command className="w-4 h-4" /> <span className="text-[10px] font-black">SEARCH</span>
        </div>
        {(internalFilter || externalFilter) && (
            <button onClick={() => { setInternalFilter(''); if (onExternalFilterChange) onExternalFilterChange(''); }} className="p-3 hover:bg-rose-500/20 text-rose-500 rounded-full transition-colors">
                <X className="w-5 h-5" />
            </button>
        )}
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6">
          {filteredChannels.length > 0 ? filteredChannels.map(channel => {
              const isActive = currentChannel?.id === channel.id;
              const isFav = favorites.some(f => f.id === channel.id);

              return (
                  <div
                      key={channel.id}
                      onClick={() => onSelectChannel(channel)}
                      className={`
                        group relative p-6 flex flex-col items-center justify-center text-center transition-all duration-500 cursor-pointer
                        border ${styles.layoutShape} min-w-0 active:scale-95 animate-in fade-in duration-700
                        ${isActive 
                            ? `${styles.buttonActive} shadow-[0_25px_50px_rgba(0,0,0,0.5)] scale-110 z-10 border-transparent animate-breathe` 
                            : `${styles.card} ${styles.cardHover} hover:scale-105 hover:-translate-y-2`}
                      `}
                  >
                      {/* Favorite Marker */}
                      {isFav && !isActive && (
                          <div className="absolute top-3 right-3 text-amber-500 opacity-60">
                              <Star className="w-4 h-4 fill-current animate-pulse" />
                          </div>
                      )}

                      <div className={`w-16 h-16 mb-5 rounded-3xl flex items-center justify-center overflow-hidden transition-all duration-700 group-hover:rotate-6 shadow-inner relative ${isActive ? 'bg-white/20' : 'bg-black/30 border border-white/5'}`}>
                          {channel.logo ? (
                              <img src={channel.logo} className="w-full h-full object-contain p-2.5 group-hover:scale-110 transition-transform" loading="lazy" />
                          ) : (
                              mode === 'tv' ? <Tv className={`w-8 h-8 ${isActive ? 'text-black' : 'opacity-20'}`} /> : <Radio className={`w-8 h-8 ${isActive ? 'text-black' : 'opacity-20'}`} />
                          )}
                          {isActive && <div className="absolute inset-0 bg-white/20 animate-pulse"></div>}
                      </div>

                      <div className="flex flex-col gap-2 w-full">
                          <span className={`text-[12px] font-black tracking-tighter line-clamp-2 uppercase italic leading-tight ${isActive ? 'text-black' : styles.textMain}`}>
                              {channel.name}
                          </span>
                          <span className={`text-[9px] font-black uppercase tracking-[0.2em] opacity-30 group-hover:opacity-60 transition-opacity ${isActive ? 'text-black/60' : styles.textDim}`}>
                              {channel.group || '频道'}
                          </span>
                      </div>

                      {isActive && (
                          <div className="absolute bottom-[-3px] left-1/2 -translate-x-1/2 w-1/3 h-1.5 bg-white rounded-full shadow-[0_0_15px_#fff]"></div>
                      )}
                  </div>
              );
          }) : (
              <div className="col-span-full py-32 text-center">
                  <Globe2 className="w-20 h-20 mx-auto mb-8 opacity-5 animate-pulse" />
                  <div className="opacity-20 font-black uppercase italic tracking-[0.6em] text-sm">
                      未锁定匹配信道
                  </div>
              </div>
          )}
      </div>
    </div>
  );
};

